import pandas as pd
import numpy as np

def review_ati_contributors(df):
    """
    Review candidate ATI contributors.

    ATI consumes trajectory-aware evidence
    generated by other domains.
    """

    candidate_columns = [
        # Burden
        "vital_burden_score",
        "vital_burden_score_velocity",
        "vital_burden_score_acceleration",

        # Compensation
        "compensation_reserve_score",
        "compensation_reserve_score_velocity",
        "compensation_reserve_score_acceleration",

        # Instability
        "hidden_instability_score",
        "hidden_instability_score_velocity",
        "hidden_instability_score_acceleration",
        "hidden_instability_persistence",

        # Recovery
        "recovery_instability_score",
        "recovery_momentum",

        # Re-Escalation
        "re_escalation_pressure_score",
    ]

    review_rows = []

    for col in candidate_columns:

        review_rows.append({
            "candidate_signal": col,
            "available": col in df.columns,
        })

    return pd.DataFrame(review_rows)

